[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --navy:   #1B1464;
      --navy-light: #2a1f8f;
      --yellow: #FFD930;
      --yellow-hover: #f5ce00;
      --blue:   #0066FF;
      --teal:   #00B8A9;
      --teal-light: #e6f8f7;
      --white:  #FFFFFF;
      --gray-50:  #F8FAFC;
      --gray-100: #F1F5F9;
      --gray-200: #E2E8F0;
      --gray-400: #94A3B8;
      --gray-500: #64748B;
      --gray-700: #334155;
      --gray-900: #0F172A;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.05);
      --shadow-md: 0 4px 16px rgba(0,0,0,.10);
      --shadow-lg: 0 12px 40px rgba(0,0,0,.12);
      --shadow-xl: 0 24px 64px rgba(0,0,0,.14);
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      color: var(--gray-900);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    /* ── UTILS ─────────────────────────────────────────── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .btn {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 12px 24px; border-radius: var(--radius-sm);
      font-size: 15px; font-weight: 600; cursor: pointer;
      border: none; text-decoration: none; transition: all .18s ease;
      white-space: nowrap;
    }
    .btn-primary {
      background: var(--yellow); color: var(--navy);
    }
    .btn-primary:hover { background: var(--yellow-hover); transform: translateY(-1px); box-shadow: 0 4px 16px rgba(255,217,48,.4); }
    .btn-outline {
      background: transparent; color: var(--navy);
      border: 2px solid var(--navy);
    }
    .btn-outline:hover { background: var(--navy); color: var(--white); }
    .btn-white {
      background: var(--white); color: var(--navy);
    }
    .btn-white:hover { background: var(--gray-100); transform: translateY(-1px); }
    .section-label {
      display: inline-block; font-size: 12px; font-weight: 700;
      letter-spacing: .12em; text-transform: uppercase;
      color: var(--teal); margin-bottom: 12px;
    }
    .section-title {
      font-size: clamp(28px, 4vw, 42px); font-weight: 800;
      color: var(--navy); line-height: 1.15; margin-bottom: 16px;
    }
    .section-subtitle {
      font-size: 18px; color: var(--gray-500); max-width: 560px;
    }

    /* ── HEADER ─────────────────────────────────────────── */
    header {
      position: sticky; top: 0; z-index: 100;
      background: rgba(255,255,255,.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      transition: box-shadow .2s;
    }
    header.scrolled { box-shadow: var(--shadow-md); }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 68px;
    }
    .logo {
      font-size: 22px; font-weight: 900; color: var(--navy);
      text-decoration: none; letter-spacing: -.5px;
      display: flex; align-items: center; gap: 6px;
    }
    .logo-mark {
      width: 32px; height: 32px; border-radius: 8px;
      background: var(--navy); display: flex; align-items: center; justify-content: center;
    }
    .logo-mark svg { width: 18px; height: 18px; }
    nav { display: flex; align-items: center; gap: 8px; }
    .nav-links { display: flex; align-items: center; gap: 4px; list-style: none; }
    .nav-links a {
      padding: 8px 14px; border-radius: var(--radius-sm);
      font-size: 14px; font-weight: 500; color: var(--gray-700);
      text-decoration: none; transition: all .15s;
    }
    .nav-links a:hover { background: var(--gray-100); color: var(--navy); }
    .nav-ctas { display: flex; align-items: center; gap: 8px; margin-left: 12px; }
    .btn-login {
      padding: 8px 16px; border-radius: var(--radius-sm);
      font-size: 14px; font-weight: 600; color: var(--navy);
      background: transparent; border: 1.5px solid var(--gray-200);
      cursor: pointer; text-decoration: none; transition: all .15s;
    }
    .btn-login:hover { border-color: var(--navy); }
    .btn-signup {
      padding: 8px 18px; border-radius: var(--radius-sm);
      font-size: 14px; font-weight: 600; color: var(--navy);
      background: var(--yellow); border: none;
      cursor: pointer; text-decoration: none; transition: all .15s;
    }
    .btn-signup:hover { background: var(--yellow-hover); }

    /* Hamburger */
    .hamburger {
      display: none; flex-direction: column; gap: 5px; cursor: pointer;
      background: none; border: none; padding: 6px;
    }
    .hamburger span {
      display: block; width: 24px; height: 2px;
      background: var(--navy); border-radius: 2px; transition: all .3s;
    }
    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile drawer */
    .mobile-drawer {
      display: none; position: fixed; inset: 0; z-index: 200;
    }
    .drawer-overlay {
      position: absolute; inset: 0; background: rgba(0,0,0,.4);
      backdrop-filter: blur(4px);
    }
    .drawer-panel {
      position: absolute; top: 0; right: 0; bottom: 0; width: 280px;
      background: var(--white); padding: 24px;
      display: flex; flex-direction: column; gap: 8px;
      transform: translateX(100%); transition: transform .3s cubic-bezier(.4,0,.2,1);
      box-shadow: var(--shadow-xl);
    }
    .mobile-drawer.open { display: block; }
    .mobile-drawer.open .drawer-panel { transform: translateX(0); }
    .drawer-close {
      align-self: flex-end; background: none; border: none;
      font-size: 24px; cursor: pointer; color: var(--gray-500);
      margin-bottom: 16px; padding: 4px;
    }
    .drawer-link {
      display: block; padding: 14px 16px; border-radius: var(--radius-sm);
      font-size: 16px; font-weight: 500; color: var(--gray-700);
      text-decoration: none; transition: background .15s;
    }
    .drawer-link:hover { background: var(--gray-100); color: var(--navy); }
    .drawer-divider { height: 1px; background: var(--gray-200); margin: 8px 0; }
    .drawer-btn {
      display: block; padding: 14px 16px; border-radius: var(--radius-sm);
      font-size: 16px; font-weight: 600; text-align: center;
      text-decoration: none; transition: all .15s;
    }
    .drawer-btn-login { color: var(--navy); border: 1.5px solid var(--gray-200); }
    .drawer-btn-login:hover { border-color: var(--navy); }
    .drawer-btn-signup { background: var(--yellow); color: var(--navy); margin-top: 4px; }
    .drawer-btn-signup:hover { background: var(--yellow-hover); }

    /* ── HERO ────────────────────────────────────────────── */
    .hero {
      background: linear-gradient(135deg, var(--navy) 0%, #2d1f9e 60%, #1e3a8a 100%);
      padding: 80px 0 100px;
      position: relative; overflow: hidden;
    }
    .hero::before {
      content: ''; position: absolute; inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }
    .hero-blob-1 {
      position: absolute; width: 600px; height: 600px; border-radius: 50%;
      background: radial-gradient(circle, rgba(255,217,48,.08) 0%, transparent 70%);
      top: -200px; right: -100px; pointer-events: none;
    }
    .hero-blob-2 {
      position: absolute; width: 400px; height: 400px; border-radius: 50%;
      background: radial-gradient(circle, rgba(0,184,169,.1) 0%, transparent 70%);
      bottom: -150px; left: -100px; pointer-events: none;
    }
    .hero-content { position: relative; z-index: 1; text-align: center; }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: rgba(255,217,48,.15); border: 1px solid rgba(255,217,48,.3);
      border-radius: 100px; padding: 6px 16px;
      font-size: 13px; font-weight: 600; color: var(--yellow);
      margin-bottom: 28px;
    }
    .hero-badge span { width: 6px; height: 6px; border-radius: 50%; background: var(--yellow); }
    .hero h1 {
      font-size: clamp(36px, 6vw, 68px); font-weight: 900;
      color: var(--white); line-height: 1.08; margin-bottom: 20px;
      letter-spacing: -.02em;
    }
    .hero h1 em { font-style: normal; color: var(--yellow); }
    .hero p {
      font-size: clamp(16px, 2vw, 20px); color: rgba(255,255,255,.75);
      max-width: 600px; margin: 0 auto 48px; line-height: 1.6;
    }

    /* ── SEARCH BAR ──────────────────────────────────────── */
    .search-box {
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-xl);
      padding: 8px;
      max-width: 920px; margin: 0 auto;
      display: flex; gap: 4px; align-items: stretch;
      position: relative; z-index: 10;
    }
    .search-field {
      flex: 1; position: relative; min-width: 0;
    }
    .search-field-inner {
      display: flex; align-items: center; gap: 10px;
      padding: 12px 16px; border-radius: var(--radius-md);
      transition: background .15s;
    }
    .search-field-inner:hover { background: var(--gray-50); }
    .search-field-inner:focus-within { background: var(--blue-50, #eff6ff); }
    .search-icon { color: var(--blue); flex-shrink: 0; }
    .search-field-content { flex: 1; min-width: 0; }
    .search-field-label {
      display: block; font-size: 11px; font-weight: 700;
      color: var(--gray-400); letter-spacing: .06em; text-transform: uppercase;
      margin-bottom: 2px;
    }
    .search-input {
      width: 100%; border: none; outline: none; background: transparent;
      font-size: 15px; font-weight: 500; color: var(--gray-900);
      font-family: inherit; padding: 0;
    }
    .search-input::placeholder { color: var(--gray-400); font-weight: 400; }
    .search-divider {
      width: 1px; background: var(--gray-200);
      margin: 8px 0; flex-shrink: 0;
    }
    .search-select {
      width: 100%; border: none; outline: none; background: transparent;
      font-size: 15px; font-weight: 500; color: var(--gray-900);
      font-family: inherit; cursor: pointer; appearance: none;
      padding: 0;
    }
    .search-btn {
      background: var(--blue); color: var(--white);
      border: none; border-radius: var(--radius-md);
      padding: 14px 28px; font-size: 16px; font-weight: 700;
      cursor: pointer; display: flex; align-items: center; gap: 8px;
      transition: all .18s; white-space: nowrap; flex-shrink: 0;
    }
    .search-btn:hover {
      background: #0052cc; transform: translateY(-1px);
      box-shadow: 0 8px 24px rgba(0,102,255,.35);
    }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute; top: calc(100% + 8px); left: 0; right: 0;
      background: var(--white); border-radius: var(--radius-md);
      box-shadow: var(--shadow-xl); border: 1px solid var(--gray-200);
      overflow: hidden; z-index: 50;
      display: none;
    }
    .autocomplete-dropdown.visible { display: block; }
    .autocomplete-group-label {
      padding: 8px 16px 4px; font-size: 11px; font-weight: 700;
      color: var(--gray-400); text-transform: uppercase; letter-spacing: .08em;
    }
    .autocomplete-item {
      display: flex; align-items: center; gap: 12px;
      padding: 10px 16px; cursor: pointer; transition: background .12s;
      font-size: 14px; color: var(--gray-700);
    }
    .autocomplete-item:hover { background: var(--gray-50); }
    .autocomplete-item .item-icon {
      width: 32px; height: 32px; border-radius: 8px;
      background: var(--teal-light); display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .autocomplete-item .item-icon svg { color: var(--teal); }
    .autocomplete-item .item-name { font-weight: 600; color: var(--gray-900); }
    .autocomplete-item .item-type { font-size: 12px; color: var(--gray-400); }

    /* ── STATS BAR ───────────────────────────────────────── */
    .stats-bar {
      background: var(--navy);
      padding: 0;
    }
    .stats-inner {
      display: flex; align-items: stretch; justify-content: space-around;
      flex-wrap: wrap;
    }
    .stat-item {
      flex: 1; min-width: 140px;
      display: flex; align-items: center; gap: 16px;
      padding: 24px 20px;
      border-right: 1px solid rgba(255,255,255,.1);
    }
    .stat-item:last-child { border-right: none; }
    .stat-icon-wrap {
      width: 44px; height: 44px; border-radius: 10px;
      background: rgba(255,217,48,.15); flex-shrink: 0;
      display: flex; align-items: center; justify-content: center;
    }
    .stat-icon-wrap svg { color: var(--yellow); }
    .stat-number {
      font-size: 26px; font-weight: 900; color: var(--white);
      line-height: 1; letter-spacing: -.02em;
    }
    .stat-label { font-size: 13px; color: rgba(255,255,255,.55); margin-top: 3px; }

    /* ── SPECIALTIES ─────────────────────────────────────── */
    .specialties { padding: 96px 0; background: var(--white); }
    .specialties-header { text-align: center; margin-bottom: 56px; }
    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
      gap: 16px;
    }
    .specialty-card {
      background: var(--white); border: 1.5px solid var(--gray-200);
      border-radius: var(--radius-lg); padding: 28px 20px;
      text-align: center; cursor: pointer;
      transition: all .2s cubic-bezier(.4,0,.2,1);
      text-decoration: none; display: block;
    }
    .specialty-card:hover {
      border-color: var(--blue); box-shadow: var(--shadow-lg);
      transform: translateY(-4px);
    }
    .specialty-card:hover .spec-icon-wrap { background: var(--blue); }
    .specialty-card:hover .spec-icon-wrap svg { color: var(--white); }
    .spec-icon-wrap {
      width: 64px; height: 64px; border-radius: 16px;
      background: var(--teal-light); margin: 0 auto 16px;
      display: flex; align-items: center; justify-content: center;
      transition: all .2s;
    }
    .spec-icon-wrap svg { color: var(--teal); transition: color .2s; }
    .spec-name {
      font-size: 15px; font-weight: 700; color: var(--navy); margin-bottom: 6px;
    }
    .spec-desc { font-size: 12px; color: var(--gray-500); line-height: 1.4; }

    /* ── HOW IT WORKS ────────────────────────────────────── */
    .how-it-works { padding: 96px 0; background: var(--gray-50); }
    .how-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center; }
    .how-steps { display: flex; flex-direction: column; gap: 40px; }
    .how-step { display: flex; gap: 20px; align-items: flex-start; }
    .step-number {
      width: 48px; height: 48px; border-radius: 12px;
      background: var(--navy); color: var(--yellow);
      font-size: 18px; font-weight: 900;
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .step-content {}
    .step-title { font-size: 18px; font-weight: 700; color: var(--navy); margin-bottom: 8px; }
    .step-desc { font-size: 15px; color: var(--gray-500); line-height: 1.6; }
    .how-visual {
      background: linear-gradient(135deg, var(--navy) 0%, #2d1f9e 100%);
      border-radius: var(--radius-lg); padding: 40px;
      position: relative; overflow: hidden; min-height: 420px;
      display: flex; flex-direction: column; justify-content: flex-end;
    }
    .how-visual::before {
      content: ''; position: absolute; inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='40' height='40' viewBox='0 0 40 40' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Cpath d='M0 38.59l2.83-2.83 1.41 1.41L1.41 40H0v-1.41zM0 1.4l2.83 2.83 1.41-1.41L1.41 0H0v1.41zM38.59 40l-2.83-2.83 1.41-1.41L40 38.59V40h-1.41zM40 1.41l-2.83 2.83-1.41-1.41L38.59 0H40v1.41z'/%3E%3C/g%3E%3C/svg%3E");
    }
    .visual-card {
      position: relative; z-index: 1;
      background: rgba(255,255,255,.1); border: 1px solid rgba(255,255,255,.2);
      border-radius: var(--radius-md); padding: 20px;
      backdrop-filter: blur(12px);
    }
    .visual-profile {
      display: flex; align-items: center; gap: 14px; margin-bottom: 16px;
    }
    .visual-avatar {
      width: 52px; height: 52px; border-radius: 14px;
      background: linear-gradient(135deg, var(--teal), var(--blue));
      display: flex; align-items: center; justify-content: center;
      font-size: 20px; font-weight: 800; color: var(--white); flex-shrink: 0;
    }
    .visual-name { font-size: 16px; font-weight: 700; color: var(--white); }
    .visual-specialty { font-size: 13px; color: rgba(255,255,255,.6); margin-top: 2px; }
    .visual-stars { color: var(--yellow); font-size: 14px; letter-spacing: 2px; }
    .visual-slots { display: flex; gap: 8px; flex-wrap: wrap; }
    .visual-slot {
      padding: 6px 12px; border-radius: 6px;
      font-size: 12px; font-weight: 600; cursor: pointer;
      transition: all .15s;
    }
    .visual-slot.available {
      background: rgba(0,184,169,.2); color: var(--teal);
      border: 1px solid rgba(0,184,169,.3);
    }
    .visual-slot.selected {
      background: var(--teal); color: var(--white); border-color: var(--teal);
    }
    .visual-floating {
      position: absolute; top: 24px; right: 24px; z-index: 2;
      background: var(--yellow); color: var(--navy);
      border-radius: 10px; padding: 10px 14px;
      font-size: 13px; font-weight: 700;
      box-shadow: 0 4px 16px rgba(255,217,48,.4);
    }

    /* ── TESTIMONIALS ────────────────────────────────────── */
    .testimonials { padding: 96px 0; background: var(--white); }
    .testimonials-header { text-align: center; margin-bottom: 56px; }
    .testimonials-grid {
      display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 24px;
    }
    .testimonial-card {
      background: var(--white); border: 1.5px solid var(--gray-200);
      border-radius: var(--radius-lg); padding: 32px;
      transition: box-shadow .2s;
    }
    .testimonial-card:hover { box-shadow: var(--shadow-lg); }
    .testimonial-stars { color: var(--yellow); font-size: 18px; margin-bottom: 16px; letter-spacing: 2px; }
    .testimonial-text {
      font-size: 15px; color: var(--gray-700); line-height: 1.7;
      margin-bottom: 24px; font-style: italic;
    }
    .testimonial-text::before { content: '\201C'; }
    .testimonial-text::after { content: '\201D'; }
    .testimonial-author { display: flex; align-items: center; gap: 12px; }
    .author-avatar {
      width: 44px; height: 44px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: 16px; font-weight: 800; color: var(--white); flex-shrink: 0;
    }
    .author-avatar.av1 { background: linear-gradient(135deg, #f093fb, #f5576c); }
    .author-avatar.av2 { background: linear-gradient(135deg, #4facfe, #00f2fe); }
    .author-avatar.av3 { background: linear-gradient(135deg, #43e97b, #38f9d7); }
    .author-name { font-size: 14px; font-weight: 700; color: var(--navy); }
    .author-location { font-size: 12px; color: var(--gray-400); margin-top: 2px; }

    /* ── MOBILE APP PROMO ────────────────────────────────── */
    .app-promo {
      background: linear-gradient(135deg, var(--navy) 0%, #2d1f9e 100%);
      padding: 96px 0; overflow: hidden; position: relative;
    }
    .app-promo::after {
      content: ''; position: absolute;
      width: 500px; height: 500px; border-radius: 50%;
      background: radial-gradient(circle, rgba(255,217,48,.07), transparent 70%);
      top: -200px; right: -100px; pointer-events: none;
    }
    .app-inner {
      display: grid; grid-template-columns: 1fr 1fr; gap: 64px;
      align-items: center; position: relative; z-index: 1;
    }
    .app-content {}
    .app-title {
      font-size: clamp(28px, 4vw, 44px); font-weight: 900;
      color: var(--white); margin-bottom: 16px; line-height: 1.15;
    }
    .app-subtitle { font-size: 17px; color: rgba(255,255,255,.7); margin-bottom: 32px; line-height: 1.6; }
    .app-features { display: flex; flex-direction: column; gap: 12px; margin-bottom: 40px; }
    .app-feature {
      display: flex; align-items: center; gap: 12px;
      font-size: 14px; color: rgba(255,255,255,.8);
    }
    .app-feature-dot {
      width: 8px; height: 8px; border-radius: 50%; background: var(--teal); flex-shrink: 0;
    }
    .app-btns { display: flex; gap: 12px; flex-wrap: wrap; }
    .store-btn {
      display: flex; align-items: center; gap: 10px;
      background: rgba(255,255,255,.1); border: 1.5px solid rgba(255,255,255,.2);
      border-radius: 12px; padding: 12px 20px;
      color: var(--white); text-decoration: none; cursor: pointer;
      transition: all .18s; backdrop-filter: blur(8px);
    }
    .store-btn:hover { background: rgba(255,255,255,.18); transform: translateY(-2px); }
    .store-btn-text-sm { font-size: 11px; color: rgba(255,255,255,.65); }
    .store-btn-text-lg { font-size: 15px; font-weight: 700; }
    .app-phone-wrap {
      display: flex; justify-content: center; align-items: center;
      position: relative;
    }
    .app-phone {
      width: 240px; height: 460px;
      background: linear-gradient(160deg, #1e293b, #0f172a);
      border-radius: 36px; border: 6px solid #334155;
      position: relative; box-shadow: 0 32px 80px rgba(0,0,0,.5);
      overflow: hidden;
    }
    .phone-screen {
      position: absolute; inset: 0;
      background: linear-gradient(160deg, #0066FF 0%, var(--navy) 60%);
      display: flex; flex-direction: column; padding: 24px 16px;
    }
    .phone-header {
      font-size: 10px; font-weight: 700; color: rgba(255,255,255,.5);
      text-align: center; margin-bottom: 20px;
    }
    .phone-search {
      background: rgba(255,255,255,.1); border-radius: 8px;
      padding: 8px 12px; display: flex; align-items: center; gap: 8px;
      margin-bottom: 16px;
    }
    .phone-search-text { font-size: 11px; color: rgba(255,255,255,.6); }
    .phone-card {
      background: rgba(255,255,255,.1); border-radius: 10px; padding: 12px;
      margin-bottom: 8px; display: flex; align-items: center; gap: 10px;
    }
    .phone-card-avatar {
      width: 36px; height: 36px; border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
      font-size: 13px; font-weight: 800; color: var(--white); flex-shrink: 0;
    }
    .phone-card-name { font-size: 11px; font-weight: 700; color: var(--white); }
    .phone-card-specialty { font-size: 9px; color: rgba(255,255,255,.55); margin-top: 1px; }
    .phone-badge {
      position: absolute; bottom: 24px; right: -20px;
      background: var(--yellow); color: var(--navy);
      border-radius: 10px; padding: 8px 12px;
      font-size: 11px; font-weight: 700; box-shadow: var(--shadow-md);
      white-space: nowrap;
    }

    /* ── FOOTER ──────────────────────────────────────────── */
    footer {
      background: var(--gray-900); color: var(--white);
      padding: 64px 0 32px;
    }
    .footer-top {
      display: grid;
      grid-template-columns: 1.5fr repeat(4, 1fr);
      gap: 40px; margin-bottom: 48px;
    }
    .footer-brand {}
    .footer-logo {
      font-size: 20px; font-weight: 900; color: var(--white);
      text-decoration: none; display: flex; align-items: center; gap: 8px; margin-bottom: 12px;
    }
    .footer-logo-mark {
      width: 28px; height: 28px; background: var(--yellow);
      border-radius: 6px; display: flex; align-items: center; justify-content: center;
    }
    .footer-logo-mark svg { color: var(--navy); }
    .footer-tagline { font-size: 14px; color: rgba(255,255,255,.5); line-height: 1.6; max-width: 220px; }
    .footer-col-title {
      font-size: 12px; font-weight: 700; letter-spacing: .1em;
      text-transform: uppercase; color: rgba(255,255,255,.4); margin-bottom: 16px;
    }
    .footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
    .footer-links a {
      font-size: 14px; color: rgba(255,255,255,.6); text-decoration: none; transition: color .15s;
    }
    .footer-links a:hover { color: var(--white); }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,.08);
      padding-top: 24px; display: flex; align-items: center;
      justify-content: space-between; flex-wrap: wrap; gap: 12px;
    }
    .footer-copy { font-size: 13px; color: rgba(255,255,255,.4); }
    .footer-badge {
      background: rgba(255,217,48,.1); border: 1px solid rgba(255,217,48,.2);
      color: var(--yellow); font-size: 12px; font-weight: 600;
      padding: 4px 12px; border-radius: 100px;
    }

    /* ── RESPONSIVE ──────────────────────────────────────── */
    @media (max-width: 768px) {
      .nav-links, .nav-ctas { display: none; }
      .hamburger { display: flex; }

      .search-box { flex-direction: column; gap: 0; padding: 12px; }
      .search-divider { width: 100%; height: 1px; margin: 4px 0; }
      .search-field-inner { border-radius: var(--radius-sm); }
      .search-btn { width: 100%; justify-content: center; margin-top: 4px; }

      .stats-inner { flex-direction: column; }
      .stat-item { border-right: none; border-bottom: 1px solid rgba(255,255,255,.08); }
      .stat-item:last-child { border-bottom: none; }

      .how-inner { grid-template-columns: 1fr; gap: 48px; }
      .how-visual { min-height: 300px; }

      .app-inner { grid-template-columns: 1fr; gap: 48px; }
      .app-phone-wrap { display: none; }

      .footer-top { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: 1 / -1; }
    }

    @media (max-width: 480px) {
      .hero { padding: 60px 0 80px; }
      .specialties, .how-it-works, .testimonials, .app-promo { padding: 64px 0; }
      .specialties-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-top { grid-template-columns: 1fr; }
    }
  </style>
</head>
