<script>
  // Header scroll shadow
  const header = document.getElementById('site-header');
  window.addEventListener('scroll', () => {
    header.classList.toggle('scrolled', window.scrollY > 8);
  }, { passive: true });

  // Mobile drawer
  const hamburger = document.getElementById('hamburger-btn');
  const drawer = document.getElementById('mobile-drawer');
  const drawerOverlay = document.getElementById('drawer-overlay');
  const drawerClose = document.getElementById('drawer-close');

  function openDrawer() {
    drawer.classList.add('open');
    hamburger.classList.add('open');
    hamburger.setAttribute('aria-expanded', 'true');
    document.body.style.overflow = 'hidden';
  }
  function closeDrawer() {
    drawer.classList.remove('open');
    hamburger.classList.remove('open');
    hamburger.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
  }

  hamburger.addEventListener('click', () => {
    drawer.classList.contains('open') ? closeDrawer() : openDrawer();
  });
  drawerOverlay.addEventListener('click', closeDrawer);
  drawerClose.addEventListener('click', closeDrawer);
  document.addEventListener('keydown', e => { if (e.key === 'Escape') closeDrawer(); });

  // Autocomplete
  const searchInput = document.getElementById('search-input');
  const dropdown = document.getElementById('autocomplete-list');
  const items = dropdown.querySelectorAll('.autocomplete-item');

  const suggestions = [
    { name: 'Primary Care', type: 'Specialty' },
    { name: 'Dentist', type: 'Specialty' },
    { name: 'Dermatologist', type: 'Specialty' },
    { name: 'Psychiatrist', type: 'Specialty' },
    { name: 'Eye Doctor', type: 'Specialty' },
    { name: 'Orthopedic Surgeon', type: 'Specialty' },
    { name: 'Back pain', type: 'Condition' },
    { name: 'Anxiety', type: 'Condition' },
    { name: 'Acne', type: 'Condition' },
    { name: 'Dr. Sarah Chen', type: 'Doctor' },
  ];

  searchInput.addEventListener('input', () => {
    const val = searchInput.value.trim().toLowerCase();
    if (val.length === 0) {
      dropdown.classList.remove('visible');
      searchInput.setAttribute('aria-expanded', 'false');
      return;
    }
    // Show/hide items based on match
    let anyVisible = false;
    items.forEach(item => {
      const match = item.dataset.value.toLowerCase().includes(val);
      item.style.display = match ? '' : 'none';
      if (match) anyVisible = true;
    });
    dropdown.classList.toggle('visible', anyVisible);
    searchInput.setAttribute('aria-expanded', String(anyVisible));
  });

  searchInput.addEventListener('focus', () => {
    if (searchInput.value.trim().length > 0) {
      dropdown.classList.add('visible');
    }
  });

  document.addEventListener('click', e => {
    if (!e.target.closest('.search-field')) {
      dropdown.classList.remove('visible');
      searchInput.setAttribute('aria-expanded', 'false');
    }
  });

  items.forEach(item => {
    item.addEventListener('click', () => {
      searchInput.value = item.dataset.value;
      dropdown.classList.remove('visible');
      searchInput.setAttribute('aria-expanded', 'false');
      searchInput.focus();
    });
    item.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        searchInput.value = item.dataset.value;
        dropdown.classList.remove('visible');
        searchInput.focus();
      }
    });
  });

  // Keyboard navigation in dropdown
  searchInput.addEventListener('keydown', e => {
    if (!dropdown.classList.contains('visible')) return;
    const visible = [...items].filter(i => i.style.display !== 'none');
    const focused = document.activeElement;
    const idx = visible.indexOf(focused);
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      (visible[idx + 1] || visible[0])?.focus();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      (visible[idx - 1] || visible[visible.length - 1])?.focus();
    } else if (e.key === 'Escape') {
      dropdown.classList.remove('visible');
      searchInput.setAttribute('aria-expanded', 'false');
    }
  });

  // Specialty card clicks
  document.querySelectorAll('.specialty-card').forEach(card => {
    card.addEventListener('click', e => {
      e.preventDefault();
      const specialty = card.dataset.specialty;
      searchInput.value = specialty;
      document.getElementById('search-input').dispatchEvent(new Event('input'));
      document.querySelector('.hero').scrollIntoView({ behavior: 'smooth' });
    });
  });

  // Search button
  document.getElementById('search-btn').addEventListener('click', () => {
    const query = searchInput.value.trim();
    const location = document.getElementById('location-input').value.trim();
    if (!query) {
      searchInput.focus();
      searchInput.style.outline = '2px solid #f5576c';
      setTimeout(() => searchInput.style.outline = '', 1500);
      return;
    }
    // Would navigate to search results in a real app
    alert(`Searching for: ${query}${location ? ' in ' + location : ''}`);
  });

  // Animate stats on scroll
  const statNumbers = document.querySelectorAll('.stat-number');
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.style.opacity = '1';
        entry.target.style.transform = 'translateY(0)';
      }
    });
  }, { threshold: 0.3 });

  statNumbers.forEach(el => {
    el.style.opacity = '0';
    el.style.transform = 'translateY(12px)';
    el.style.transition = 'opacity .5s ease, transform .5s ease';
    observer.observe(el);
  });

  // Specialty card stagger animation
  const specCards = document.querySelectorAll('.specialty-card');
  const specObserver = new IntersectionObserver(entries => {
    entries.forEach((entry, i) => {
      if (entry.isIntersecting) {
        setTimeout(() => {
          entry.target.style.opacity = '1';
          entry.target.style.transform = 'translateY(0)';
        }, i * 60);
      }
    });
  }, { threshold: 0.1 });

  specCards.forEach(card => {
    card.style.opacity = '0';
    card.style.transform = 'translateY(16px)';
    card.style.transition = 'opacity .4s ease, transform .4s ease, box-shadow .2s, border-color .2s';
    specObserver.observe(card);
  });
</script>
